CREATE FUNCTION public.max_seats_per_booking(p_screen_id uuid) RETURNS int LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT greatest(CASE WHEN sc.block1_rows>0 THEN sc.block1_cols ELSE 0 END,CASE WHEN sc.block2_rows>0 THEN sc.block2_cols ELSE 0 END,CASE WHEN sc.block3_rows>0 THEN sc.block3_cols ELSE 0 END) FROM public.screen sc WHERE sc.id=p_screen_id $$;
CREATE FUNCTION public.isolated_seats(p_screening_id uuid,p_assume_booked uuid[] DEFAULT '{}') RETURNS SETOF uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT s.id FROM public.seat s JOIN public.screening ss ON ss.screen_id=s.screen_id WHERE ss.id=p_screening_id AND NOT(s.id=ANY(coalesce(p_assume_booked,'{}'::uuid[]))) AND NOT EXISTS(SELECT 1 FROM public.booking_seat bs WHERE bs.screening_id=p_screening_id AND bs.seat_id=s.id AND bs.is_active) AND NOT EXISTS(SELECT 1 FROM public.seat n WHERE n.screen_id=s.screen_id AND n.row_index=s.row_index AND n.block_no=s.block_no AND n.col_no=s.col_no-1 AND NOT(n.id=ANY(coalesce(p_assume_booked,'{}'::uuid[]))) AND NOT EXISTS(SELECT 1 FROM public.booking_seat nb WHERE nb.screening_id=p_screening_id AND nb.seat_id=n.id AND nb.is_active)) AND NOT EXISTS(SELECT 1 FROM public.seat n WHERE n.screen_id=s.screen_id AND n.row_index=s.row_index AND n.block_no=s.block_no AND n.col_no=s.col_no+1 AND NOT(n.id=ANY(coalesce(p_assume_booked,'{}'::uuid[]))) AND NOT EXISTS(SELECT 1 FROM public.booking_seat nb WHERE nb.screening_id=p_screening_id AND nb.seat_id=n.id AND nb.is_active)) $$;
CREATE FUNCTION public.count_new_isolated_seats(p_screening_id uuid,p_seat_ids uuid[]) RETURNS int LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*)::int FROM public.isolated_seats(p_screening_id,p_seat_ids) a(id) WHERE NOT EXISTS(SELECT 1 FROM public.isolated_seats(p_screening_id) b(id) WHERE b.id=a.id) $$;
CREATE FUNCTION public.get_seat_status(p_screening_id uuid) RETURNS TABLE(seat_id uuid,row_label text,row_index int,col_no int,block_no smallint,status text,is_isolated boolean,price int,starts_at timestamptz,max_seats int,discount_active boolean,discount_pct int,screening_started boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'NOT_LOGGED_IN: Please log in to book seats.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.screening ss WHERE ss.id=p_screening_id) THEN RAISE EXCEPTION 'SCREENING_NOT_FOUND: The screening does not exist.'; END IF; RETURN QUERY SELECT s.id,s.row_label,s.row_index,s.col_no,s.block_no,CASE WHEN EXISTS(SELECT 1 FROM public.booking_seat bs WHERE bs.screening_id=ss.id AND bs.seat_id=s.id AND bs.is_active) THEN 'BOOKED' ELSE 'AVAILABLE' END,EXISTS(SELECT 1 FROM public.isolated_seats(p_screening_id) i(id) WHERE i.id=s.id),ss.price,ss.starts_at,public.max_seats_per_booking(ss.screen_id),now()>ss.starts_at-interval '20 minutes' AND now()<ss.starts_at,20,now()>=ss.starts_at FROM public.screening ss JOIN public.seat s ON s.screen_id=ss.screen_id WHERE ss.id=p_screening_id ORDER BY s.row_index,s.col_no; END $$;
CREATE FUNCTION public.book_seats(p_screening_id uuid,p_seat_ids uuid[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_screening public.screening%ROWTYPE; v_count int; v_max int; v_booking_id uuid; v_no text; v_seq bigint; v_discount boolean; v_isolated uuid[]; v_total int; v_seats jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'NOT_LOGGED_IN: Please log in to book seats.'; END IF; IF public.is_admin() THEN RAISE EXCEPTION 'ADMIN_CANNOT_BOOK: Administrator accounts cannot book seats.'; END IF; SELECT ss.* INTO v_screening FROM public.screening ss WHERE ss.id=p_screening_id; IF NOT FOUND OR now()>=v_screening.starts_at THEN RAISE EXCEPTION 'SCREENING_STARTED: This screening has already started and can no longer be booked.'; END IF; v_count:=cardinality(p_seat_ids); IF p_seat_ids IS NULL OR v_count=0 OR EXISTS(SELECT 1 FROM unnest(p_seat_ids) x(id) WHERE x.id IS NULL) OR (SELECT count(DISTINCT x.id) FROM unnest(p_seat_ids) x(id))<>v_count THEN RAISE EXCEPTION 'NO_SEATS: Select at least one seat.'; END IF; v_max:=public.max_seats_per_booking(v_screening.screen_id); IF v_count>v_max THEN RAISE EXCEPTION 'TOO_MANY_SEATS: You can book up to % seats at a time in this screen.',v_max; END IF; IF (SELECT count(*) FROM public.seat s WHERE s.screen_id=v_screening.screen_id AND s.id=ANY(p_seat_ids))<>v_count THEN RAISE EXCEPTION 'SEAT_NOT_IN_SCREEN: The seat information is out of date. The seat map has been refreshed.'; END IF; IF v_count>=2 AND (SELECT count(DISTINCT(s.row_index,s.block_no))<>1 OR max(s.col_no)-min(s.col_no)+1<>v_count FROM public.seat s WHERE s.id=ANY(p_seat_ids)) THEN RAISE EXCEPTION 'NOT_CONTIGUOUS: Seats booked together must be next to each other in the same row, with no aisle between them.'; END IF; PERFORM pg_advisory_xact_lock(hashtext(p_screening_id::text)); IF EXISTS(SELECT 1 FROM public.booking_seat bs WHERE bs.screening_id=p_screening_id AND bs.seat_id=ANY(p_seat_ids) AND bs.is_active) THEN RAISE EXCEPTION 'SEAT_TAKEN: Seat already booked. One or more of the selected seats have just been booked. Please choose your seats again.'; END IF; IF public.count_new_isolated_seats(p_screening_id,p_seat_ids)>=2 THEN RAISE EXCEPTION 'TOO_MANY_ISOLATED: This selection would leave two or more isolated seats (single empty seats between booked seats, aisles or walls). Please choose other seats.'; END IF; v_discount:=now()>v_screening.starts_at-interval '20 minutes' AND now()<v_screening.starts_at; SELECT coalesce(array_agg(i.id),'{}'::uuid[]) INTO v_isolated FROM public.isolated_seats(p_screening_id) i(id); SELECT sum(CASE WHEN v_discount AND s.id=ANY(v_isolated) THEN round(v_screening.price*(100-20)/100.0)::int ELSE v_screening.price END)::int INTO v_total FROM public.seat s WHERE s.id=ANY(p_seat_ids); v_seq:=nextval('public.booking_no_seq'); v_no:='CO-'||to_char(now() AT TIME ZONE 'Asia/Seoul','YYYYMMDD')||'-'||lpad(v_seq::text,greatest(4,length(v_seq::text)),'0'); INSERT INTO public.booking(booking_no,member_id,screening_id,status,total_amount) VALUES(v_no,auth.uid(),p_screening_id,'CONFIRMED',v_total) RETURNING id INTO v_booking_id; INSERT INTO public.booking_seat(booking_id,screening_id,seat_id,is_active,unit_price,is_discounted) SELECT v_booking_id,p_screening_id,s.id,true,CASE WHEN v_discount AND s.id=ANY(v_isolated) THEN round(v_screening.price*(100-20)/100.0)::int ELSE v_screening.price END,v_discount AND s.id=ANY(v_isolated) FROM public.seat s WHERE s.id=ANY(p_seat_ids); SELECT jsonb_agg(jsonb_build_object('seat_id',s.id,'row_label',s.row_label,'col_no',s.col_no,'unit_price',bs.unit_price,'is_discounted',bs.is_discounted) ORDER BY s.row_index,s.col_no) INTO v_seats FROM public.booking_seat bs JOIN public.seat s ON s.id=bs.seat_id WHERE bs.booking_id=v_booking_id; RETURN jsonb_build_object('booking_id',v_booking_id,'booking_no',v_no,'total_amount',v_total,'seats',v_seats); EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'SEAT_TAKEN: Seat already booked. One or more of the selected seats have just been booked. Please choose your seats again.'; END $$;
REVOKE ALL ON FUNCTION public.max_seats_per_booking(uuid),public.isolated_seats(uuid,uuid[]),public.count_new_isolated_seats(uuid,uuid[]) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.get_seat_status(uuid),public.book_seats(uuid,uuid[]) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.get_seat_status(uuid),public.book_seats(uuid,uuid[]) TO anon,authenticated;